select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Tavus Conversational Video Agents', 'Jotform AI Agents', 'Khanmigo', 'Cleo', 'Semrush Ads AI Agent', 'Circleback', 'Sourcery', 'Momentic', 'Sentry Seer', 'Mintlify Writing Agent', 'Slack AI', 'Box AI Agents', 'Front Autopilot', 'Linear Agent', 'Gamma') order by e.name;
